  4	public final class RadixSort {
  5	    private static final int RADIX = 10;
  6	
  7	    private RadixSort() {
  8	    }
  9	
 10	    public static void sort(int[] values) {
 11	        sortValidated(requireSupportedValues(values));
 12	    }
 13	
 14	    public static int[] sortedCopy(int[] values) {
 15	        int[] validatedValues = requireSupportedValues(values);
 16	        int[] copy = Arrays.copyOf(validatedValues, validatedValues.length);
 17	        sortValidated(copy);
 18	        return copy;
 19	    }
 20	
 21	    private static void sortValidated(int[] values) {
 22	        if (values.length < 2) {
 23	            return;
 24	        }
 25	
 26	        SortWorkspace workspace = new SortWorkspace(values.length);
 27	        int maxValue = findMax(values);
 28	        int[] source = values;
 29	        int[] target = workspace.buffer;
 30	        boolean valuesContainSortedResult = true;
 31	
 32	        for (int exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
 33	            countingSortByDigit(source, target, workspace.counts, exponent);
 34	
 35	            int[] previousSource = source;
 36	            source = target;
 37	            target = previousSource;
 38	            valuesContainSortedResult = !valuesContainSortedResult;
 39	        }
 40	
 41	        if (!valuesContainSortedResult) {
 42	            System.arraycopy(source, 0, values, 0, values.length);
 43	        }
 44	    }
 45	
 46	    private static int[] requireSupportedValues(int[] values) {
 47	        Objects.requireNonNull(values, "values");
 48	
 49	        for (int value : values) {
 50	            if (value < 0) {
 51	                throw new IllegalArgumentException(
 52	                    "Radix sort only supports non-negative integers."
 53	                );
 54	            }
 55	        }
 56	
 57	        return values;
 58	    }
 59	
 60	    private static int findMax(int[] values) {
 61	        int maxValue = values[0];
 62	        for (int index = 1; index < values.length; index++) {
 63	            if (values[index] > maxValue) {
 64	                maxValue = values[index];
 65	            }
 66	        }
 67	        return maxValue;
 68	    }
 69	
 70	    private static void countingSortByDigit(
 71	        int[] source,
 72	        int[] target,
 73	        int[] counts,
 74	        int exponent
 75	    ) {
 76	        Arrays.fill(counts, 0);
 77	
 78	        for (int value : source) {
 79	            counts[digitAt(value, exponent)]++;
 80	        }
 81	
 82	        for (int digit = 1; digit < RADIX; digit++) {
 83	            counts[digit] += counts[digit - 1];
 84	        }
 85	
 86	        for (int index = source.length - 1; index >= 0; index--) {
 87	            int value = source[index];
 88	            int digit = digitAt(value, exponent);
 89	            target[--counts[digit]] = value;
 90	        }
 91	    }
 92	
 93	    private static int digitAt(int value, int exponent) {
 94	        return (value / exponent) % RADIX;
 95	    }
 96	
 97	    private static final class SortWorkspace {
 98	        private final int[] buffer;
 99	        private final int[] counts = new int[RADIX];
100	
101	        private SortWorkspace(int length) {
102	            this.buffer = new int[length];
103	        }
104	    }
105	}

